                setDisabledOkruhy() {
                    const content = this;
                    let povUprava = !content.ReadOnly && content.currentDtoOkruh != null;
                    let str = "";
                    content.actions.act_NewRoot.enabled(!content.ReadOnly);
                    content.actions.act_NewOkruh.enabled(povUprava);
                    if (povUprava) {
                        //povolení k přístupu
                        povUprava = content.currentDtoOkruh.ixs_fun_spravce == null || content.ParametrPehPovAdmin;
                        if (povUprava) {
                            povUprava = !content.isUsedOkruh(content.currentDtoOkruh);
                            if (povUprava) {
                                if (content.dtoOkruhyView.getDataRows(false, "filter").filter((r) => r.ixs_oot_nad === content.currentDtoOkruh.ixs_oot).length > 0) {
                                    str = "jres:29122419"; //RC 29122419 : Okruh kritérií má podřízené okruhy.
                                }
                                else {
                                    if (content.dtoOtazkyView.getCount("filter") > 0)
                                        str = "jres:29122420"; //RC 29122420 : Okruh kritérií má podřízené hodnotící kritéria.
                                }
                            }
                            else {
                                str = "jres:29122416"; //RC 29122416 : Okruh kritérií je již použit v hodnocení.
                            }
                            content.actions.act_NewKriteria.enabled(true);
                            content.actions.act_NewKriteria.update({ tooltip: "" });
                        }
                        else {
                            str = "jres:29122417"; //RC 29122417 : Přihlášený uživatel nemá práva na úpravu okruhu hodnotících kritérií.
                            content.actions.act_NewKriteria.enabled(false);
                            content.actions.act_NewKriteria.update({ tooltip: str });
                        }
                        content.actions.act_DeleteOkruh.enabled(str === "");
                        content.actions.act_DeleteOkruh.update({ tooltip: str });
                    }
                    else {
                        content.actions.act_NewKriteria.enabled(false);
                        content.actions.act_NewKriteria.update({ tooltip: "" });
                        content.actions.act_DeleteOkruh.enabled(false);
                        content.actions.act_DeleteOkruh.update({ tooltip: "" });
                    }
                    content
                        .findForms("form_okruhy")
                        .findFields("nazev,popis,oblast_sz")
                        .gfield("option", "disabled", !(povUprava || (content.DebugMode && content.currentDtoOkruh != null)));
                    content.findForms("form_okruhy").findFields("ixs_fun_spravce").gfield("option", "disabled", !povUprava);
                }
                isUsedOkruh(node) {
                    const content = this;
                    if (node == null)
                        return false;
                    const rows = content.dtoOtazkyView
                        .getDataRows(false, "data")
                        .filter((r) => r.ixs_oot === node.ixs_oot && r.aktivita === 100 && (r.je_nav === 1 || r.je_vzo === 1));
                    if (rows.length > 0)
                        return true;
                    const children = content.dtoOkruhyView.getDataRows(false, "filter").filter((r) => r.ixs_oot_nad === node.ixs_oot);
                    for (let i = 0; i < children.length; i++) {
                        if (content.isUsedOkruh(children[i]))
                            return true;
                    }
                    return false;
                }
