                loadData() {
                    const content = this;
                    //#region Generace
                    const def_gen = $.Deferred();
                    if (content.DtoGenerace == null && content.IxsGen != null) {
                        const guid = Gordic.Utils.generateGuid();
                        content.beginOperation({ id: guid, text: "jres:34900091" }); //RC 34900091 : Načítám generaci hodnocení
                        content.isl.PehGenerace.list({ filters: { ixs_gen: content.IxsGen, aktivni: false } })
                            .getData()
                            .then((result) => {
                            if (result.length > 0)
                                content.DtoGenerace = result[0];
                            def_gen.resolve();
                        })
                            .always(() => {
                            content.endOperation(guid);
                        });
                    }
                    else
                        def_gen.resolve();
                    //#endregion Generace
                    //#region SYM
                    const def_sym = $.Deferred();
                    if (content.IxsGen != null) {
                        const guid = Gordic.Utils.generateGuid();
                        content.beginOperation({ id: guid, text: "jres:34900109" }); //RC 34900109 : Načítám SYM
                        content.isl.PehGenerace.listSymGen({ filters: { ixs_gen: content.IxsGen, aktivni: true } })
                            .getData()
                            .then((result) => {
                            //Content.dtoCharSymList = result;
                            if (content.Action === WebClient.EnumActions.Copy) {
                                if (result.length > 0) {
                                    result.forEach((item) => {
                                        item.ixs_gen = null;
                                        item.dat_zmena = null;
                                        item.zmenu_prov = null;
                                        item.zmenu_prov_txt = null;
                                        item.aktivita = 100;
                                    });
                                    content.jeZmenaCharSym = true;
                                }
                            }
                            const filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                return meta.data.aktivita === 100;
                            });
                            const view = new Gordic.Data.View(result, { key: "ixs_sym,poradi", processors: { filterProcessor } });
                            content.grid.ggrid("setData", view);
                            //if (content.autoSirkaSloupcu) {
                            //    content.grid.ggrid("option", "columns", content.getGridFormatAutoWidth());
                            //    content.grid.ggrid("refresh");
                            //}
                            def_sym.resolve();
                        })
                            .always(() => {
                            content.endOperation(guid);
                        });
                    }
                    else {
                        const filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                            return meta.data.aktivita === 100;
                        });
                        const view = new Gordic.Data.View([], { key: "ixs_sym", processors: { filterProcessor } });
                        content.grid.ggrid("setData", view);
                        def_sym.reject();
                    }
                    //#endregion SYM
                    def_gen.then(() => {
                        if (content.DtoGenerace != null) {
                            //debugger;
                            content.findForms("form").findFields().gfield("model", "apply", content.DtoGenerace, { initialValues: true });
                            if (content.DtoGenerace.log == null || content.DtoGenerace.log.trim() === "") {
                                $("#log").gtab("hide");
                                content.findFormSections("logSection").hide();
                            }
                            else
                                content.findForms("form_log").findFields().gfield("model", "apply", content.DtoGenerace, { initialValues: true });
                        }
                        def_sym.always(() => {
                            //čekám na načtení hodnot doformu
                            content
                                .findFields("nazev")
                                .gfield("getValueAsync")
                                .then(() => {
                                content
                                    .findFields("dat_uzavreno_od")
                                    .gfield("getValueAsync")
                                    .then(() => {
                                    content.setDisabled();
                                });
                            });
                        });
                    });
                }
                setDisabled() {
                    const content = this;
                    const view = content.grid.ggrid("getView");
                    content.actions.act_Generate.enabled(!content.hasChanged() && content.JePovUprava && !(content.DtoGenerace.ixs_gen == null || content.DtoGenerace.gener_vyp === WebClient.TypGenerovano.ano));
                    content.actions.act_Hodnoceni.enabled(!(content.DtoGenerace == null || content.DtoGenerace.ixs_gen == null || content.DtoGenerace.gener_vyp === WebClient.TypGenerovano.ne));
                    content.findFields("nazev,dat_uzavreno_od").gfield("option", "disabled", !content.JePovUprava || content.DtoGenerace.gener_vyp !== WebClient.TypGenerovano.ne);
                    content.actions.act_Add.enabled(content.JePovUprava && content.DtoGenerace.gener_vyp === WebClient.TypGenerovano.ne);
                    content.actions.act_Detail.enabled(view.getCount("filter") > 0);
                    content.actions.act_Delete.enabled(content.JePovUprava && view.getCount("filter") > 0 && content.DtoGenerace.gener_vyp !== WebClient.TypGenerovano.ano);
                    content.actions.act_ChangeHtel.enabled(content.JePovUprava && view.getCount("filter") > 0 && content.DtoGenerace.gener_vyp === WebClient.TypGenerovano.ne);
                    content.updateButton();
                }
