                upozorneniPredUlozenim() {
                    const content = this;
                    const def = $.Deferred();
                    let ret = true;
                    const osoby = content.grid.ggrid("getView").getDataRows(false, "data");
                    //Deferred k dialogům, aby počkal na reakci uživatele
                    const def_otazky = $.Deferred();
                    const def_nadHod = $.Deferred();
                    const def_hod = $.Deferred();
                    const field = content.findFields("dat_otazky_od");
                    if (field.gfield("hasValue") && field.gfield("getValue") < new Date()) {
                        content.dialogs
                            .confirm("Uložení změn", "jres:29122467 jres:29120841") //RC 29122467 : Datum počátku hodnocení leží v minulosti.
                            .on("no", () => {
                            ret = false;
                            def_otazky.reject();
                            def.resolve(ret);
                        })
                            .on("yes", () => {
                            def_otazky.resolve();
                        });
                    }
                    else
                        def_otazky.resolve();
                    def_otazky.then(() => {
                        if (content.NadHtelZobr > 0 &&
                            osoby.filter((r) => r.aktivita === 100 && r.je_ppv && r.je_gen !== 1 && r.sym_nazev == null && r.nh_htel_ppv == null).length > 0) {
                            content.dialogs
                                .confirm("jres:29120033", "jres:29122730 jres:29120841") //RC 29122730 : Některá z osob nemá nadřízeného hodnotitele nebo se nedá zjistit - těm se nebude vytvářet vyhodnocení nadřízeného hodnotitele.
                                .on("no", () => {
                                ret = false;
                                def_nadHod.reject();
                                def.resolve(ret);
                            })
                                .on("yes", () => {
                                def_nadHod.resolve();
                            });
                        }
                        else
                            def_nadHod.resolve();
                    });
                    def_nadHod.then(() => {
                        if (content.NadHtelZobr > 0 &&
                            osoby.filter((r) => r.aktivita === 100 && r.je_ppv && r.je_gen !== 1 && r.htel_ppv != null && r.nh_htel_ppv != null && r.htel_ppv === r.nh_htel_ppv)
                                .length > 0) {
                            content.dialogs
                                .confirm("jres:29120033", "jres:32730140 jres:29120841") //RC 32730140 : Některá z osob má hodnotitele shodného s nadřízeným hodnotitele - těm se nebude vytvářet vyhodnocení nadřízeného hodnotitele.
                                .on("no", () => {
                                ret = false;
                                def_hod.reject();
                                def.resolve(ret);
                            })
                                .on("yes", () => {
                                def_hod.resolve();
                            });
                        }
                        else
                            def_hod.resolve();
                    });
                    def_hod.always(() => {
                        def_nadHod.always(() => {
                            def_otazky.always(() => {
                                def.resolve(ret);
                            });
                        });
                    });
                    return def.promise();
                }
                //#region Validace
                osobyValid() {
                    const content = this;
                    const view = content.grid.ggrid("getView");
                    const osoby = view.getDataRows(false, "data");
                    let valid = false;
                    if (osoby.length === 0 || osoby.filter((r) => r.aktivita === 100 && r.je_ppv).length === 0) {
                        content.showFlash("jres:29122456", "error"); //RC 29122456 : Generace nemá vybrány žádné osoby.
                    }
                    else if (osoby.filter((r) => r.aktivita === 100 && r.je_ppv && r.je_gen !== 1 && r.sym_nazev && r.htel_ppv == null).length > 0) {
                        content.showFlash("jres:29122687", "error"); //RC 29122687 : Některá z osob nemá hodnotitele.
                        const errorProcessor = new Gordic.Data.ErrorProcessor((value) => {
                            if (value.aktivita === 100 && value.je_ppv && value.je_gen !== 1 && value.sym_nazev && value.htel_ppv == null) {
                                return [{ message: "jres:34900119" }]; //RC 34900119 : Osoba nemá hodnotitele.
                            }
                            else
                                return [];
                        });
                        view.process({ errorProcessor }, true);
                    }
                    else if (content.findFields("vzory_rozsah").gfield("getValue") === WebClient.RozsahVzoru.DleKompModelu &&
                        osoby.filter((r) => r.aktivita === 100 && r.je_ppv && r.je_gen !== 1 && r.ixs_kmo == null).length > 0) {
                        content.showFlash("jres:29122725", "error"); //RC 29122725 : Některá z osob nemá nastaven kompetenční model.
                        const errorProcessor = new Gordic.Data.ErrorProcessor((value) => {
                            if (value.aktivita === 100 && value.je_ppv && value.je_gen !== 1 && value.ixs_kmo == null) {
                                return [{ message: "jres:34900120" }]; //RC 34900120 : Osoba nemá nastaven kompetenční model.
                            }
                            else
                                return [];
                        });
                        view.process({ errorProcessor }, true);
                    }
                    else {
                        valid = true;
                    }
                    return valid;
                }
                //#endregion Validace
                kontrolaGenerace() {
                    const content = this;
                    const view = content.grid.ggrid("getView");
                    const osoby = view.getDataRows(false, "data");
                    if (content.DtoGenerace.hni_rozsah === WebClient.RozsahHodnocenych.VybranePpv) {
                        if (osoby.length === 0) {
                            content.dialogs.warning("jres:29122718", "jres:29122717".format(content.DtoGenerace.nazev)); //RC 29122717 : Generace „{0}“ nemá k okamžiku generování hodnocené.
                            return false;
                        }
                        let rows = osoby.filter((r) => r.aktivita === 100 && r.je_ppv);
                        if (rows.length === 0) {
                            content.dialogs.warning("jres:29122718", "jres:29122717".format(content.DtoGenerace.nazev)); //RC 29122717 : Generace „{0}“ nemá k okamžiku generování hodnocené.
                            return false;
                        }
                        if (content.DtoGenerace.h_htel_vyber === WebClient.TypHodnotitele.VybranePpv && content.DtoGenerace.h_htel_ppv != null) {
                            return true;
                        }
                        rows = rows.filter((r) => r.aktivita === 100 && r.je_ppv && r.htel_ppv == null);
                        if (rows.length === 0) {
                            return true;
                        }
                        let ret = true;
                        const cas = content.DtoGenerace.dat_otazky_od == null ? new Date() : parseDate(content.DtoGenerace.dat_otazky_od);
                        rows.forEach(async (item) => {
                            const guid = Gordic.Utils.generateGuid();
                            content.beginOperation({ id: guid, text: "jres:34900121" }); //RC 34900121 : Načítám vedoucího
                            await content.isl.PehGenerace.getVedouciPpv({
                                ixs_ppv: item.ixs_ppv,
                                datum: cas,
                                podle_vyn: true,
                                mimo_ved_odd: content.HtelVyb === 4,
                                zastup_9: false,
                                zastup_66: false,
                            })
                                .get()
                                .then((result) => {
                                if (result == null) {
                                    content.dialogs.warning("jres:29122718", "jres:29122719".format(item.nazev)); //RC 29122719 : Hodnocený „{0}“ nemá nadřízeného.
                                    ret = false;
                                }
                                if (result === item.ixs_ppv) {
                                    content.dialogs.warning("jres:jres:29122718", "jres:29122720".format(item.nazev)); //RC 29122720 : Hodnocený „{0}“ nemůže být zároveň hodnotitelem.
                                    ret = false;
                                }
                            })
                                .always(() => {
                                content.endOperation(guid);
                            });
                            if (!ret)
                                return null;
                        });
                        if (!ret)
                            return ret;
                    }
                    return true;
                }
                saveHodForm() {
                    const content = this;
                    const field = content.findForms("form").findFields("ixs_vzo");
                    const ixs_vzo = field.gfield("getValue").ixs_vzo;
                    const nazev = field.gfield("getValue").nazev;
                    content.jeZmenaVzoru =
                        content.dtoHodForm == null || content.dtoHodForm.ixs_gen == null || content.dtoHodForm.ixs_vzo == null
                            ? field.gfield("hasValue")
                            : content.dtoHodForm.ixs_vzo !== ixs_vzo;
                    if (content.jeZmenaVzoru) {
                        if (content.dtoHodForm == null) {
                            content.dtoHodForm = {
                                aktivita: 100,
                                typ_clen: WebClient.TypClena.Vzor,
                                zarazeni: WebClient.RozsahZarazeniClena.Vzory,
                            };
                        }
                        else {
                            content.dtoHodForm.dat_zmena = null;
                        }
                        content.dtoHodForm.sxs_clen = ixs_vzo;
                        content.dtoHodForm.ixs_vzo = ixs_vzo;
                        content.dtoHodForm.nazev = nazev;
                    }
                }
