                    content.actions.act_Add.enabled(content.JePovUprava && content.DtoGenerace.gener_vyp === WebClient.TypGenerovano.ne && form.findFields("obd_hod").gfield("hasValue"));
                    content.actions.act_Detail.enabled(content.JePovUprava && view.getDataRows().length > 0);
