                osobyValid() {
                    const content = this;
                    const view = content.grid.ggrid("getView");
                    const osoby = view.getDataRows(false, "data");
                    let valid = osoby.length > 0 && osoby.filter((r) => r.aktivita === 100).length > 0;
                    if (osoby.length === 0 || osoby.filter((r) => r.aktivita === 100 && r.je_ppv).length === 0) {
                        content.showFlash("jres:29122456", "error"); //RC 29122456 : Generace nemá vybrány žádné osoby.
                    }
                    else if (osoby.filter((r) => r.aktivita === 100 && r.je_ppv && r.je_gen !== 1 && r.sym_nazev && r.htel_ppv == null).length > 0) {
                        content.showFlash("jres:29122687", "error"); //RC 29122687 : Některá z osob nemá hodnotitele.
                        const errorProcessor = new Gordic.Data.ErrorProcessor((value) => {
                            if (value.aktivita === 100 && value.je_ppv && value.je_gen !== 1 && value.sym_nazev && value.htel_ppv == null) {
                                return [{ message: "jres:34900119" }]; //RC 34900119 : Osoba nemá hodnotitele.
                            }
                            else
                                return [];
                        });
                        view.process({ errorProcessor }, true);
                    }
                    else {
                        valid = true;
                    }
                    return valid;
                }
                saveHodForm() {
                    const content = this;
                    const field = content.findForms("form").findFields("ixs_vzo");
                    const ixs_vzo = field.gfield("getValue").ixs_vzo;
                    const nazev = field.gfield("getValue").nazev;
                    content.jeZmenaVzoru =
                        content.dtoHodForm == null || content.dtoHodForm.ixs_gen == null || content.dtoHodForm.ixs_vzo == null
                            ? field.gfield("hasValue")
                            : content.dtoHodForm.ixs_vzo !== ixs_vzo;
                    if (content.jeZmenaVzoru) {
                        if (content.dtoHodForm == null) {
                            content.dtoHodForm = {
                                aktivita: 100,
                                typ_clen: WebClient.TypClena.Vzor,
                                zarazeni: WebClient.RozsahZarazeniClena.Vzory,
                            };
                        }
                        else {
                            content.dtoHodForm.dat_zmena = null;
                        }
                        content.dtoHodForm.sxs_clen = ixs_vzo;
                        content.dtoHodForm.ixs_vzo = ixs_vzo;
                        content.dtoHodForm.nazev = nazev;
                    }
                }
                newDataGen() {
                    const content = this;
                    content.DtoGenerace = {
                        ixs_thd: content.IxsThd,
                        zdroj_faze: content.Faze,
                        dat_vznik: new Date(),
                        ixs_ppv_autor: content.IxsPpvFun,
                        ixs_ppv_spravce: content.IxsPpvFun,
                        d_hle_rozsah: WebClient.RozsahHodnotitelu.Zadni,
                        d_hle_vsechny_ppv: false,
                        d_hle_vybrane_ppv: false,
                        d_hle_vyb_skup_clen: false,
                        d_hle_nadrizeny: false,
                        d_hle_je_sebehod: false,
                        d_hle_bez_sebehod: false,
                        generovano: 0,
                        gener_vyp: 0,
                        poc_vygen_hodn: 0,
                        poc_clen: 0,
                        poc_clen_vygen: 0,
                        aktivita: 100,
                    };
                    const rok = new Date().getMonth() > 9 ? new Date().getFullYear() : new Date().getFullYear() - 1;
                    content.DtoGenerace.dat_obdobi_od = new Date(rok, 0, 1);
                    content.DtoGenerace.dat_obdobi_do = new Date(rok, 11, 31);
                    content.DtoGenerace.nazev = "jres:29122490"; //RC 29122490 : Služební hodnocení
                    content.DtoGenerace.typ_hodnoceni = WebClient.TypHodnoceni.sluzPomer;
                    content.DtoGenerace.hni_rozsah = WebClient.RozsahHodnocenych.VybranePpv;
                    content.DtoGenerace.d_hle_rozsah = WebClient.RozsahHodnotitelu.Nadrizeny;
                    content.DtoGenerace.d_hle_nadrizeny = true;
                    content.DtoGenerace.vzory_rozsah = WebClient.RozsahVzoru.Vybrane;
                    content.DtoGenerace.h_htel_vyber = WebClient.TypHodnotitele.Nadrizeny;
                    content.DtoGenerace.nh_htel_vyber = WebClient.TypHodnotitele.VybranePpv;
                    content.JePovUprava = !content.readOnly && content.DtoGenerace != null && content.DtoGenerace.zdroj_faze == content.Faze;
                }
                kontrolaGenerace() {
                    const content = this;
                    if (content.DtoGenerace.hni_rozsah === WebClient.RozsahHodnocenych.VybranePpv) {
                        const osoby = content.grid.ggrid("getView").getDataRows(false, "data");
                        if (osoby.length === 0) {
                            content.dialogs.warning("jres:29122718", "jres:29122717".format(content.DtoGenerace.nazev)); //RC 29122718 : Kontrola generace
                            return false;
                        }
                        let rows = osoby.filter((r) => r.aktivita === 100 && r.je_ppv);
                        if (rows.length === 0) {
                            content.dialogs.warning("jres:29122718", "jres:29122717".format(content.DtoGenerace.nazev)); //RC 29122718 : Kontrola generace
                            return false;
                        }
                        if (content.DtoGenerace.h_htel_vyber === WebClient.TypHodnotitele.VybranePpv && content.DtoGenerace.h_htel_ppv != null) {
                            return true;
                        }
                        rows = rows.filter((r) => r.aktivita === 100 && r.je_ppv && r.htel_ppv == null);
                        if (rows.length === 0) {
                            return true;
                        }
                        let ret = true;
                        const cas = content.DtoGenerace.dat_otazky_od == null ? new Date() : new Date(content.DtoGenerace.dat_otazky_od.toString());
                        rows.forEach(async (item) => {
                            const guid = Gordic.Utils.generateGuid();
                            content.beginOperation({ id: guid, text: "jres:34900121" }); //RC 34900121 : Načítám vedoucího
                            await content.isl.PehGenerace.getVedouciPpv({
                                ixs_ppv: item.ixs_ppv,
                                datum: cas,
                                podle_vyn: true,
                                mimo_ved_odd: content.HtelVyb === 4,
                                zastup_9: false,
                                zastup_66: false,
                            })
                                .get()
                                .then((result) => {
                                if (result == null) {
                                    content.dialogs.warning("jres:29122718", "jres:29122719".format(item.nazev)); //RC 29122719 : Hodnocený „{0}“ nemá nadřízeného.
                                    ret = false;
                                }
                                if (result === item.ixs_ppv) {
                                    content.dialogs.warning("jres:29122718", "jres:29122720".format(item.nazev)); //RC 29122720 : Hodnocený „{0}“ nemůže být zároveň hodnotitelem.
                                    ret = false;
                                }
                            })
                                .always(() => {
                                content.endOperation(guid);
                            });
                            if (!ret)
                                return null;
                        });
                        if (!ret)
                            return ret;
                    }
                    return true;
                }
                upozorneniPredUlozenim() {
                    const content = this;
                    const def = $.Deferred();
                    const field = content.findFields("dat_otazky_od");
                    if (field.gfield("hasValue") &&
                        field.gfield("getValue").setHours(0, 0, 0, 0) < new Date().setHours(0, 0, 0, 0) &&
                        content.DtoGenerace != null &&
                        content.DtoGenerace.gener_vyp === WebClient.TypGenerovano.ne) {
                        content.dialogs
                            .confirm("jres:29120033", "jres:29122467\njres:29120841") //RC 29122467 : Datum počátku hodnocení leží v minulosti., RC 29120841 : Chcete pokračovat?
                            .on("yes", () => {
                            def.resolve(true);
                        })
                            .on("no", () => {
                            def.resolve(false);
                        });
                    }
                    else
                        def.resolve(true);
                    return def.promise();
                }
