                                            const dto = { ...novy };
                                            dto.sxs_clen = novy.ixs_ppv;
                                            dto.typ_clen = WebClient.TypClena.Ppv;
                                            dto.zarazeni = WebClient.RozsahZarazeniClena.HodnoceniPpv;
