                                            dto.dat_zmena = null;
                                            view.updateData(dto, "add");
                                            if (zmenitNazev)
                                                content.findFields("nazev").gfield("setValue", novy.nazev + " - " + new Date(novy.ppv_od.toString()).toLocaleDateString("cs"));
