                        content.beginOperation({ id: guid, text: "jres:34900118" }); //RC 34900118 : Načítám osoby
                        content.isl.PehGenerace.listOsobyGen({ filters: { ixs_gen: content.IxsGen, aktivni: true, logovatGdpr: content.ParametrZdaLogovatGDPR } })
                            .getData()
