                //#endregion Validace
                //nastavení celk. hodnocení za oblast a váhu hodnocené oblasti
                setCelkHodSum() {
                    const content = this;
                    let ixsBod = "";
                    let soucet = new Decimal(0);
                    let pocet = 0;
                    const viewOta = content.grid_krit_ota.ggrid("getView");
                    const otazky = viewOta.getDataRows(false, "data");
                    const otazka = content.grid_krit_ota.ggrid("getSelection")[0];
                    const node = content.grid_krit_tree.ggrid("getSelection")[0];
                    if (otazka != null) {
                        ixsBod = otazka.ixs_bod;
                        otazky.forEach((item) => {
                            if (item.podtyp_ota === WebClient.TypOtazky.Bodovaci) {
                                if (item.body_htel != null) {
                                    soucet = soucet.plus(item.body_htel);
                                    pocet++;
                                }
                                if (ixsBod === "")
                                    ixsBod = item.ixs_bod;
                            }
                        });
                    }
                    else {
                        if (node != null) {
                            const rows = otazky.filter((r) => r.ixs_oot_nad === node.ixs_oot);
                            rows.forEach((item) => {
                                if (item.podtyp_ota === WebClient.TypOtazky.Bodovaci) {
                                    if (item.body_htel != null) {
                                        soucet = soucet.plus(item.body_htel);
                                        pocet++;
                                    }
                                    if (ixsBod === "")
                                        ixsBod = item.ixs_bod;
                                }
                            });
                        }
                        else {
                            content.findForms("form_kriteria").findFields().gfield("clear");
                        }
                    }
                    if (pocet === 0)
                        content.findForms("form_kriteria").findFields().gfield("clear");
                    else
                        content.findForms("form_kriteria").findFields("suma").gfield("setValue", soucet.round().toString());
                }
                vypoctiCelkVysledek() {
                    const content = this;
                    let soucetHtel = new Decimal(0);
                    let pocetHtel = 0;
                    const view = content.grid_krit_ota.ggrid("getView");
                    const otazky = view.getDataRows(false, "data");
                    const rows = otazky.filter((r) => r.podtyp_ota === WebClient.TypOtazky.Bodovaci && r.aktivita_htel === 100);
                    rows.forEach((item) => {
                        if (item.body_htel != null) {
                            soucetHtel = soucetHtel.plus(item.body_htel);
                            pocetHtel++;
                        }
                    });
                    content.vysledekHod = soucetHtel.toDP(0);
                    content
                        .findForms("form_detail")
                        .findFields("vysledek")
                        .gfield("setValue", content.vysledekHod == null ? "" : content.vysledekHod.toString());
                }
                bodovaNormovane(hodnota, nejlepsi, nejhorsi) {
                    let ret = new Decimal(0);
                    if (nejlepsi.equals(nejhorsi))
                        return ret;
                    else {
                        ret = hodnota.minus(nejhorsi).dividedBy(nejlepsi.minus(nejhorsi)).toDP(3, Decimal.ROUND_HALF_CEIL);
                        return ret;
                    }
                }
                openedTab() {
                    const content = this;
                    content.zobrOtaDleOkruhu = true;
                    if (content.grid_krit_tree.ggrid("getView").getCount("data") === 0) {
                        const viewOta = content.grid_krit_ota.ggrid("getView");
                        const otazky = viewOta.getDataRows(false, "data");
                        const treeProcessor = new Gordic.Data.Tree(Gordic.Data.Tree.parentIdOrganizer("ixs_oot_nad"), {
                            defaultState: "open",
                        });
                        const nodes = [];
                        otazky.forEach((item) => {
                            if (item.ixs_oot_nad != null && !nodes.some((r) => r.ixs_oot === item.ixs_oot_nad))
                                nodes.push(content.dtoOkruhyList.filter((r) => r.ixs_oot === item.ixs_oot_nad)[0]);
                            if (!nodes.some((r) => r.ixs_oot === item.ixs_oot))
                                nodes.push(content.dtoOkruhyList.filter((r) => r.ixs_oot === item.ixs_oot)[0]);
                        });
                        const view = new Gordic.Data.View(nodes, { key: "ixs_oot", processors: { tree: treeProcessor } });
                        content.grid_krit_tree.ggrid("setData", view);
                    }
                    else {
                        const sel = content.grid_krit_tree.ggrid("getSelection")[0];
                        content.grid_krit_tree.ggrid("activeRow", { ixs_oot: sel.ixs_oot });
                    }
                }
                closedTab() {
                    const content = this;
                    content.zobrOtaDleOkruhu = false;
                    content.grid_krit_ota.ggrid("getView").process({ filterProcessor: null }, true);
                    //content.grid_krit_ota.ggrid("option", "columns", content.getGridFormatOtazkyAutoWidth());
                }
