                    if (field.gfield("option", "disabled") === true && !content.isEdit)
                        return;
                    const valid = field.gfield("hasValue") || content.Hodnoceni.stav_hod < WebClient.StavHodnoceni.Nadrizeni;
                    if (!valid) {
                        if (field.gfield("getErrors").length === 0) {
                            field.gfield("setError", {
                                message: "jres:29122535", //RC 29122535 : Nebyl zadán podpis hodnotitele.
                                errorType: "error",
                                stopping: false,
                            });
                        }
                        field.gfield("focus");
                        content.tab_vlastnosti.gtab("open");
                        content.tab_vlastnosti.gtab("scrollIntoView");
                    }
                    else
                        field.gfield("resetErrors");
                    content.jePredatelne = content.jePredatelne && valid;
