                    const content = this;
                    content.zobrOtaDleOkruhu = false;
                    const view = content.tab_krit_ota.ggrid("getView");
                    view.process({ filterProcessor: null }, true);
                    //content.tab_krit_ota.ggrid("option", "columns", content.getGridFormatOtazkyAutoWidth());
