                setVlasnosti() {
                    const content = this;
                    //debugger;
                    const jeSpravce = content.Hodnoceni != null && content.jePPVSpravovanPrihOso(content.Hodnoceni.ixs_ppv_hneho);
                    content.actions.act_Delete.enabled(!content.readOnly && jeSpravce && content.Hodnoceni.aktivita === 100);
                    content.actions.act_Generace.visible(jeSpravce);
                    content.actions.act_Generace.enabled(!content.readOnly);
                    content.actions.act_Print.enabled(!content.readOnly && content.Hodnoceni != null && content.Hodnoceni.aktivita === 100);
                    content.actions.act_Print.visible(content.Hodnoceni == null || content.Hodnoceni.ixp == null);
                    content.actions.act_Open.enabled(!content.readOnly && content.Hodnoceni != null && content.Hodnoceni.aktivita === 100);
                    content.actions.act_Open.visible(content.Hodnoceni != null && content.Hodnoceni.ixp != null);
                    const jeAkt = !content.readOnly && content.Hodnoceni != null && content.Hodnoceni.aktivita === 100 && content.dtoVyhodHneno1 != null && content.dtoDilciHod1 != null;
                    content.jePrihlHtelAkt =
                        jeAkt &&
                            ((content.JePrvniHod && content.dtoDilciHod1.ixs_esu_hodnotitel == content.IxsEsuFun) ||
                                (!content.JePrvniHod && content.dtoDilciHod2 != null && content.dtoDilciHod2.ixs_esu_hodnotitel == content.IxsEsuFun));
                    content.jePrihlHnyAkt = jeAkt && content.Hodnoceni.ixs_esu_hneho == content.IxsEsuFun;
                    content.jsouVyjadreni1Edit = content.jePrihlHnyAkt && content.Hodnoceni.stav_hod_1 === 500;
                    content.findForms("form_hodnoceny").findFormSections("section_hodnoceny1").findFields().gfield("option", "disabled", !content.jsouVyjadreni1Edit);
                    content.jsouVyjadreni2Edit = content.jePrihlHnyAkt && content.Hodnoceni.stav_hod_2 === 500;
                    content.findForms("form_hodnoceny").findFormSections("section_hodnoceny2").findFields().gfield("option", "disabled", !content.jsouVyjadreni1Edit);
                    content.jsouNNVEdit =
                        content.jePrihlHtelAkt && ((content.JePrvniHod && content.Hodnoceni.stav_hod_1 === 200) || (!content.JePrvniHod && content.Hodnoceni.stav_hod_2 === 200));
                    content.actions.act_Insert.enabled(content.jsouNNVEdit);
                    content.actions.act_Cut.enabled(content.jsouNNVEdit &&
                        ((content.JePrvniHod && content.dtoPozadavky1List != null && content.dtoPozadavky1List.length > 0) ||
                            (!content.JePrvniHod && content.dtoPozadavky2List != null && content.dtoPozadavky2List.length > 0)));
                    content.jePovEditVypHod1 =
                        content.jePrihlHtelAkt &&
                            content.dtoDilciHod1 != null &&
                            content.dtoDilciHod1.stav_dil === 20 &&
                            content.dtoDilciHod1.ixs_esu_hodnotitel === content.IxsEsuFun &&
                            content.JePrvniHod &&
                            content.Hodnoceni.stav_hod_1 === 200 &&
                            new Date().getTime() >= parseDate(content.Hodnoceni.dat_otazky_od_1).getTime();
                    content.jePovEditVypHod2 =
                        content.jePrihlHtelAkt &&
                            content.dtoDilciHod2 != null &&
                            content.dtoDilciHod2.stav_dil === 20 &&
                            content.dtoDilciHod2.ixs_esu_hodnotitel === content.IxsEsuFun &&
                            !content.JePrvniHod &&
                            content.Hodnoceni.stav_hod_2 === 200 &&
                            new Date().getTime() >= parseDate(content.Hodnoceni.dat_otazky_od_2).getTime();
                    content.updateButtons();
                }
                jePPVSpravovanPrihOso(ixs_ppv) {
                    const content = this;
                    if (content.DebugMode)
                        return true;
                    switch (content.ParametrPehSpravPPV) {
                        case 10: //žádné
                            return false;
                        case 30: //podřízené
                            return (ixs_ppv == null ||
                                ixs_ppv == "" ||
                                (content.IxsPpvPodAll != null &&
                                    content.IxsPpvPodAll.some((val) => {
                                        val === ixs_ppv;
                                    })));
                        case 90: //všechny
                            return true;
                        default:
                            return false;
                    }
                }
                setBody() {
                    const content = this;
                    content.bodovaniOtazek = [];
                    const guid = Gordic.Utils.generateGuid();
                    content.beginOperation({ id: guid, text: "jres:34900082" }); //RC 34900082 : Načítám body
                    content.isl.PehAdministraceHod.listBody({ filters: { ixs_bod: null } })
                        .getData()
                        .then((result) => {
                        const seznamOtazek = [];
                        const ixsBod = result.map((val) => {
                            return val.ixs_bod;
                        });
                        ixsBod.forEach((item) => {
                            if (!seznamOtazek.includes(item))
                                seznamOtazek.push(item);
                        });
                        seznamOtazek.forEach((item) => {
                            const rows = result.filter((r) => r.ixs_bod === item).sort((a, b) => parseFloat(a.hodnota.toString()) - parseFloat(b.hodnota.toString()));
                            if (rows.length > 0) {
                                const hodnoty = [];
                                hodnoty[0] = { hodnota_txt: "", hodnota: null }; // je-li zahrnut prázdný řádek, vkládá se na začátek
                                for (let i = 0; i < rows.length; i++) {
                                    const str = "{0} - {1}".format(new Decimal(rows[i].hodnota).toDP(3).toString(), rows[i].nazev);
                                    hodnoty[i + 1] = { hodnota_txt: str, hodnota: new Decimal(rows[i].hodnota) };
                                }
                                content.bodovaniOtazek.push({ ixs_bod: item, hodnoty: hodnoty });
                            }
                        });
                    })
                        .always(() => {
                        content.endOperation(guid);
                    });
                }
