                    const vyjadreni_s1 = content.findForms("form_hodnoceny").findFormSections("section_hodnoceny1").findFields("vyjadreni_s");
                    const vyjadreni_s2 = content.findForms("form_hodnoceny").findFormSections("section_hodnoceny2").findFields("vyjadreni_s");
