                getRoky() {
                    const content = this;
                    const guid = Gordic.Utils.generateGuid();
                    content.beginOperation({ id: guid, text: "jres:34900165" }); //RC 34900165 : Načítám roky generací
                    content.isl.PehHodnoceni.getRokyHod({ vse: true, aktivni: true, konec_obdobi: content.konec_obdobi, typ_hodnoceni: content.TypHodnoceni })
                        .get()
                        .done((result) => {
                        //debugger;
                        if (content.roky == null)
                            content.roky = [];
                        let max = 0;
                        result.forEach((item) => {
                            if (max < item)
                                max = item;
                            this.roky.push({
                                rok: item,
                                rok_txt: item === 0 ? "vše" : item.toString(),
                            });
                        });
                        const form_filter = new Gordic.Forms.Form({ name: "form_filter", layoutDescriptor: "L2M2S1" })
                            .addSection()
                            .addRow({ label: "jres:29121143" }) //RC 29121143 : Rok
                            //není filter na KonecObdobi, (defaultne je true v readeru)
                            .addField("gselectbox", 
                        /*Prefabs.Select.gCisReaderRokPehsgen(),*/ {
                            name: "rok",
                            dropdown: true /*serverFilters: { typ_hodnoceni: Content.Typ_Hodnoceni }*/,
                            itemTemplate: "{rok_txt}",
                            helperColumns: ["rok_txt"],
                            /*model: "model.rok = value.rok",*/ data: content.roky,
                            initialValue: content.roky.filter((r) => r.rok === max)[0],
                        });
                        content.filterpanel.gfilterpanel({
                            filterViewMode: FilterViewMode.Simple,
                            forms: [form_filter],
                            autoLoadAfter: ["CreatePanel"],
                            apply: function (event, obj) {
                                content.filter = obj.filter;
                                if (content.grid.ggrid("getView").getCount() === 0) {
                                    content.actions.act_Load?.run();
                                }
                                else {
                                    if (obj.filter != null && obj.filter.rok.rok > 0) {
                                        let filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                            return true;
                                        });
                                        switch (content.TypHodnoceni) {
                                            case WebClient.TypHodnoceni.veZkusebniDobe:
                                                filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                                    return (parseDate(meta.data.dat_uzavreno_od_1).getTime() >= new Date(obj.filter.rok.rok, 0, 1).getTime() &&
                                                        parseDate(meta.data.dat_uzavreno_od_1).getTime() < new Date(obj.filter.rok.rok + 1, 0, 1).getTime());
                                                });
                                                break;
                                            case WebClient.TypHodnoceni.periodicke:
                                                if (content.JeCS || content.JeGBNS) {
                                                    filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                                        return (parseDate(meta.data.dat_konec_obd).getTime() >= new Date(obj.filter.rok.rok, 0, 1).getTime() &&
                                                            parseDate(meta.data.dat_konec_obd).getTime() < new Date(obj.filter.rok.rok + 1, 0, 1).getTime());
                                                    });
                                                }
                                                else {
                                                    filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                                        return (parseDate(meta.data.dat_uzavreno_od).getTime() >= new Date(obj.filter.rok.rok, 0, 1).getTime() &&
                                                            parseDate(meta.data.dat_uzavreno_od).getTime() < new Date(obj.filter.rok.rok + 1, 0, 1).getTime());
                                                    });
                                                }
                                                break;
                                            case WebClient.TypHodnoceni.vzdelavacidAkce:
                                                filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                                    return (parseDate(meta.data.dat_uzavreno_od).getTime() >= new Date(obj.filter.rok.rok, 0, 1).getTime() &&
                                                        parseDate(meta.data.dat_uzavreno_od).getTime() < new Date(obj.filter.rok.rok + 1, 0, 1).getTime());
                                                });
                                            case WebClient.TypHodnoceni.charSYM:
                                                filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                                    return (parseDate(meta.data.dat_uzavreno_od).getTime() >= new Date(obj.filter.rok.rok, 0, 1).getTime() &&
                                                        parseDate(meta.data.dat_uzavreno_od).getTime() < new Date(obj.filter.rok.rok + 1, 0, 1).getTime());
                                                });
                                                break;
                                            case WebClient.TypHodnoceni.statZam:
                                            case WebClient.TypHodnoceni.sluzPomer:
                                            case WebClient.TypHodnoceni.vzdPlany:
                                            case WebClient.TypHodnoceni.neurceno:
                                            default:
                                                filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                                    return (parseDate(meta.data.dat_konec_obd).getTime() >= new Date(obj.filter.rok.rok, 0, 1).getTime() &&
                                                        parseDate(meta.data.dat_konec_obd).getTime() < new Date(obj.filter.rok.rok + 1, 0, 1).getTime());
                                                });
                                                break;
                                        }
                                        content.grid.ggrid("getView").process({ filterProcessor }, true);
                                    }
                                    else {
                                        const filterProcessor = new Gordic.Data.FilterProcessor((meta) => {
                                            return true;
                                        });
                                        content.grid.ggrid("getView").process({ filterProcessor }, true);
                                    }
                                    //if (content.autoSirkaSloupcu) {
                                    //    content.grid.ggrid("option", "columns", content.getGridFormatAutoWidth());
                                    //    content.grid.ggrid("refresh");
                                    //}
                                }
                            },
                        });
                    })
                        .always(() => {
                        content.endOperation(guid);
                    });
                }
                jePPVSpravovanPrihOso(ixs_ppv) {
                    const Content = this;
                    switch (Content.ParametrPehSpravPPV) {
                        case 10: //žádné
                            return false;
                        case 30: //podřízené
                            return (ixs_ppv == null ||
                                ixs_ppv == "" ||
                                (Content.IxsPpvPodAll != null &&
                                    Content.IxsPpvPodAll.some((val) => {
                                        val === ixs_ppv;
                                    })));
                        case 90: //všechny
                            return true;
                        default:
                            return false;
                    }
                }
