                //#region Funkce
                JeEsu(ixs_esu) {
                    const Content = this;
                    if (Content.NacteneZaznamy == null || Content.NacteneZaznamy.length == 0 || ixs_esu == null || "") {
                        return false;
                    }
                    for (let i = 0; i < Content.NacteneZaznamy.length; i++) {
                        if (Content.NacteneZaznamy[i].ixs_esu == ixs_esu) {
                            return true;
                        }
                    }
                    return false;
                }
                GetCtvrtRok() {
                    const Content = this;
                    const today = new Date();
                    const ctvrtRok = today.getMonth() / 3;
                    const mesicOd = ctvrtRok * 3;
                    const dat_od = new Date(today.getFullYear(), mesicOd === 0 ? 0 : mesicOd - 1, 1);
                    const temp = new Date(dat_od.setMonth(dat_od.getMonth() + 3));
                    const dat_do = new Date(temp.setDate(temp.getDate() - 1));
                    return { dat_od: new Date(today.getFullYear(), mesicOd === 0 ? 0 : mesicOd - 1, 1), dat_do: dat_do };
                }
